  --bg-2: #0a1c22;
  --panel: rgba(9, 24, 30, 0.84);
  --panel-solid: #0c2027;
  --panel-soft: rgba(15, 39, 46, 0.66);
  --line: rgba(148, 210, 210, 0.18);
  --line-strong: rgba(148, 210, 210, 0.34);
  --ink: #e8f4f4;
  --muted: #90adb1;
  --faint: #5f7b80;
  --teal: #2dd4bf;
  --teal-soft: #99f6e4;
  --gold: #ffd166;
  --orange: #ff8a5b;
  --violet: #c084fc;
  --danger: #fb7185;
  --green: #5ee08a;
