  transition: transform .16s, border-color .16s;
}
.party-card:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.party-card.active { border-color: rgba(255, 209, 102, .7); box-shadow: 0 0 0 1px rgba(255,209,102,.2), var(--shadow); }
.party-card.fainted { opacity: .48; }
.party-portrait { height: 48px; border-radius: 7px; background: radial-gradient(circle at 50% 65%, rgba(45,212,191,.18), rgba(0,0,0,.18)); overflow: hidden; }
.party-portrait img { width: 100%; height: 100%; object-fit: contain; transform: scale(1.2); }
.party-name { margin-top: 4px; font-size: 8px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.party-lv { font-size: 7px; color: var(--faint); display: flex; justify-content: space-between; margin-top: 2px; }
.party-hp { height: 3px; background: rgba(255,255,255,.1); border-radius: 2px; margin-top: 3px; overflow: hidden; }
.party-hp i { display: block; height: 100%; background: var(--green); }
.party-more { width: 34px; height: 54px; border: 1px dashed var(--line); border-radius: 10px; display: grid; place-items: center; color: var(--faint); font-size: 10px; background: rgba(5,16,20,.4); cursor: pointer; }

#action-dock {
  position: absolute;
  right: 14px;
  bottom: max(14px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.action-btn {
  min-width: 58px;
  height: 58px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel);
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  box-shadow: var(--shadow);
  transition: transform .16s, background .16s, border-color .16s;
}
.action-btn span { font-size: 18px; line-height: 1; }
.action-btn small { font-size: 7px; color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.action-btn:hover { transform: translateY(-2px); border-color: var(--line-strong); background: rgba(23,58,64,.94); }
.action-btn.primary { border-color: rgba(255,209,102,.58); background: linear-gradient(180deg, rgba(255,209,102,.19), rgba(120,80,20,.28)); }
.action-btn.primary small { color: var(--gold); }

#joystick {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: 108px;
  width: 112px;
  height: 112px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: radial-gradient(circle, rgba(45,212,191,.1), rgba(4,14,18,.55));
  display: none;
  touch-action: none;
}
#joystick .stick {
  position: absolute;
  left: 50%; top: 50%;
  width: 46px; height: 46px;
  margin: -23px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #d9fffa, #2dd4bf 60%, #0f766e);
  box-shadow: 0 4px 16px rgba(0,0,0,.4), 0 0 20px rgba(45,212,191,.25);
}
#touch-run {
  position: absolute;
  right: 18px;
  bottom: 92px;
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(6,20,25,.72);
  color: var(--muted);
  display: none;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .06em;
  touch-action: none;
}
#touch-run.held { background: rgba(45,212,191,.28); color: var(--ink); }

/* ---------- toast ---------- */
#toast-stack {
  position: absolute;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 90;
  display: flex;
  flex-direction: column;
  gap: 7px;
  align-items: center;
  pointer-events: none;
  width: min(520px, 92vw);
}
.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: rgba(6, 21, 26, .94);
  box-shadow: var(--shadow);
  backdrop-filter: blur(14px);
  color: #dbeff0;
  font-size: 11px;
  line-height: 1.35;
  animation: toast-in .28s ease;
  max-width: 100%;
}
.toast::before { content: "◆"; color: var(--teal); font-size: 8px; }
.toast.good::before { color: var(--green); }
.toast.bad::before { color: var(--danger); }
.toast.quest::before { color: var(--gold); }
.toast.relic::before { color: var(--violet); }
.toast.weather::before { color: #7dd3fc; }
.toast.event::before { color: var(--orange); }
.toast.evolve::before { color: var(--violet); }
.toast.fade { animation: toast-out .25s ease forwards; }
@keyframes toast-in { from { opacity: 0; transform: translateY(-8px) scale(.97); } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-8px) scale(.97); } }

/* ---------- modal ---------- */
#modal-root { position: absolute; inset: 0; z-index: 70; pointer-events: none; }
#modal-root.open { pointer-events: auto; }
.modal-backdrop {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
  background: rgba(1, 7, 10, 0.72);
  backdrop-filter: blur(9px);
  animation: fade-in .18s ease;
  overflow-y: auto;
}
.modal {
  position: relative;
  width: min(980px, 96vw);
  max-height: 88vh;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(17, 45, 51, .97), rgba(6, 19, 24, .98));
  box-shadow: 0 30px 100px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.06);
  animation: modal-in .22s cubic-bezier(.2,.8,.2,1);
  overflow: hidden;
}
.modal.narrow { width: min(560px, 94vw); }
.modal.wide { width: min(1120px, 96vw); }
.modal-header {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 20px 22px 15px;
  border-bottom: 1px solid var(--line);
  background: radial-gradient(circle at 20% 0%, rgba(45,212,191,.08), transparent 55%);
}
.modal-kicker { color: var(--teal-soft); font-size: 8px; font-weight: 800; letter-spacing: .22em; text-transform: uppercase; margin-bottom: 5px; }
.modal-header h2 { margin: 0; font-family: Georgia, serif; font-size: clamp(21px, 2.4vw, 30px); letter-spacing: .01em; }
.modal-header p { margin: 4px 0 0; color: var(--muted); font-size: 11px; }
.modal-close {
  margin-left: auto;
  width: 34px; height: 34px;
  min-width: 34px;
  border-radius: 9px;
  border: 1px solid var(--line);
  background: rgba(5,17,21,.6);
  color: var(--muted);
  cursor: pointer;
  font-size: 15px;
}
.modal-close:hover { color: var(--ink); border-color: var(--line-strong); }
.modal-body { padding: 18px 22px 22px; overflow-y: auto; overscroll-behavior: contain; }
.modal-body::-webkit-scrollbar, .scroll::-webkit-scrollbar { width: 8px; height: 8px; }
.modal-body::-webkit-scrollbar-thumb, .scroll::-webkit-scrollbar-thumb { background: rgba(148,210,210,.2); border-radius: 10px; }
.modal-footer { display: flex; flex-wrap: wrap; gap: 9px; justify-content: flex-end; padding: 14px 22px; border-top: 1px solid var(--line); background: rgba(4,14,18,.35); }
@keyframes fade-in { from { opacity: 0; } }
@keyframes modal-in { from { opacity: 0; transform: translateY(12px) scale(.985); } }

.tabs { display: flex; gap: 5px; flex-wrap: wrap; margin-bottom: 16px; }
.tab {
  padding: 7px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(5,16,20,.4);
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}
.tab.active { color: var(--ink); border-color: rgba(45,212,191,.5); background: rgba(45,212,191,.12); }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border-radius: 99px;
  border: 1px solid currentColor;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  white-space: nowrap;
}
.chip.soft { background: rgba(255,255,255,.04); border-color: var(--line); color: var(--muted); }
.bar { height: 5px; border-radius: 5px; background: rgba(255,255,255,.1); overflow: hidden; }
.bar i { display: block; height: 100%; border-radius: inherit; }
.grid { display: grid; gap: 10px; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.grid-auto { grid-template-columns: repeat(auto-fill, minmax(145px, 1fr)); }
.section-title { display: flex; align-items: center; gap: 9px; margin: 18px 0 10px; color: var(--muted); font-size: 9px; font-weight: 800; text-transform: uppercase; letter-spacing: .16em; }
.section-title::after { content: ""; flex: 1; height: 1px; background: var(--line); }
.muted { color: var(--muted); }
.faint { color: var(--faint); }
.gold { color: var(--gold); }
.teal { color: var(--teal-soft); }
.center { text-align: center; }
.row { display: flex; align-items: center; gap: 9px; }
.spread { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.stack { display: flex; flex-direction: column; gap: 9px; }
.empty-state { padding: 34px 16px; text-align: center; color: var(--faint); font-size: 12px; border: 1px dashed var(--line); border-radius: 12px; }

/* ---------- ranch / cards ---------- */
.creature-card {
  position: relative;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: linear-gradient(180deg, rgba(19,48,54,.75), rgba(5,17,21,.88));
  padding: 9px;
  cursor: pointer;
  transition: transform .16s, border-color .16s, box-shadow .16s;
  overflow: hidden;
}
.creature-card:hover { transform: translateY(-2px); border-color: var(--line-strong); box-shadow: 0 12px 30px rgba(0,0,0,.25); }
.creature-card.active { border-color: rgba(255,209,102,.6); }
.creature-card.locked { opacity: .5; filter: grayscale(1); cursor: default; }
.creature-card .thumb {
  height: 92px;
  border-radius: 9px;
  background: radial-gradient(circle at 50% 65%, rgba(45,212,191,.15), rgba(0,0,0,.08));
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.creature-card .thumb img { width: 100%; height: 100%; object-fit: contain; transform: scale(1.06); }
.creature-card .c-name { margin-top: 7px; font-size: 11px; font-weight: 800; display: flex; justify-content: space-between; gap: 5px; }
.creature-card .c-meta { color: var(--faint); font-size: 8px; margin-top: 2px; display: flex; justify-content: space-between; }
.creature-card .c-hp { height: 3px; background: rgba(255,255,255,.1); border-radius: 3px; margin-top: 5px; overflow: hidden; }
.creature-card .c-hp i { display: block; height: 100%; }
.corner-badge { position: absolute; top: 6px; right: 6px; padding: 2px 5px; border-radius: 5px; font-size: 7px; font-weight: 800; background: rgba(5,15,20,.82); border: 1px solid var(--line); }
.team-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); display: inline-block; margin-right: 4px; }

.ranch-layout { display: grid; grid-template-columns: 300px minmax(0, 1fr); gap: 16px; }
.ranch-side { border: 1px solid var(--line); border-radius: 13px; background: rgba(4,15,19,.5); padding: 12px; }
.ranch-hero { text-align: center; padding: 8px 0 12px; }
.ranch-hero .art { height: 155px; display: flex; align-items: center; justify-content: center; }
.ranch-hero img { max-width: 100%; max-height: 100%; filter: drop-shadow(0 12px 22px rgba(0,0,0,.35)); }
.ranch-hero h3 { margin: 3px 0 2px; font-size: 20px; }
.stat-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 6px; margin: 10px 0; }
.stat-box { border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; background: rgba(255,255,255,.02); }
.stat-box span { display: block; color: var(--faint); font-size: 7px; text-transform: uppercase; letter-spacing: .1em; }
.stat-box b { font-family: var(--mono); font-size: 13px; }
.creature-detail-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.move-list { display: flex; flex-direction: column; gap: 5px; }
.move-row { display: flex; align-items: center; gap: 8px; padding: 7px 9px; border: 1px solid var(--line); border-radius: 8px; background: rgba(255,255,255,.02); font-size: 10px; }
.move-row .move-icon { width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; font-size: 11px; background: rgba(255,255,255,.05); }
.move-row .move-name { flex: 1; font-weight: 700; }
.move-row .move-power { font-family: var(--mono); color: var(--gold); font-size: 10px; }
.move-row .move-el { color: var(--muted); font-size: 8px; }
.move-row.equipped { border-color: rgba(45,212,191,.4); background: rgba(45,212,191,.06); }

/* ---------- codex ---------- */
.codex-tools { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-bottom: 12px; }
.codex-tools input {
  flex: 1;
  min-width: 180px;
  min-height: 38px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: rgba(4,15,19,.65);
  color: var(--ink);
  outline: none;
}
.codex-tools input:focus { border-color: var(--teal); }
.codex-count { color: var(--muted); font-size: 10px; }
.codex-count b { color: var(--gold); font-family: var(--mono); }
.codex-detail { display: grid; grid-template-columns: 280px minmax(0,1fr); gap: 20px; }
.codex-art { border: 1px solid var(--line); border-radius: 14px; background: radial-gradient(circle at 50% 65%, rgba(45,212,191,.14), rgba(0,0,0,.12)); display: flex; align-items: center; justify-content: center; min-height: 260px; overflow: hidden; }
.codex-art img { width: 100%; height: 100%; object-fit: contain; }
.codex-evo { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 8px; }
.evo-node { text-align: center; font-size: 8px; color: var(--muted); }
.evo-node img { width: 54px; height: 54px; object-fit: contain; border-radius: 8px; border: 1px solid var(--line); background: rgba(0,0,0,.15); }
.evo-node.current { color: var(--gold); }
.evo-node.current img { border-color: var(--gold); }
.lore-box { border-left: 2px solid var(--teal); padding: 8px 12px; color: var(--muted); font-size: 11px; line-height: 1.6; background: rgba(45,212,191,.04); border-radius: 0 8px 8px 0; margin: 12px 0; }

/* ---------- journal ---------- */
.chapter-card { border: 1px solid var(--line); border-radius: 13px; padding: 14px; background: linear-gradient(135deg, rgba(24,58,64,.6), rgba(5,16,20,.6)); }
.chapter-card.current { border-color: rgba(255,209,102,.46); box-shadow: inset 0 0 30px rgba(255,209,102,.04); }
.chapter-card.done { opacity: .72; }
.chapter-card h3 { margin: 4px 0; font-family: Georgia, serif; font-size: 20px; }
.chapter-card p { margin: 5px 0; color: var(--muted); font-size: 11px; line-height: 1.55; }
.chapter-num { color: var(--gold); font-size: 8px; letter-spacing: .18em; text-transform: uppercase; font-weight: 800; }
.quest-item { display: flex; gap: 12px; padding: 11px 12px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,.018); }
.quest-item.ready { border-color: rgba(255,209,102,.4); }
.quest-item.done { opacity: .55; }
.quest-item .q-icon { width: 30px; height: 30px; min-width: 30px; display: grid; place-items: center; border-radius: 8px; background: rgba(45,212,191,.1); color: var(--teal); }
.quest-item h4 { margin: 0 0 3px; font-size: 11px; }
.quest-item p { margin: 0; color: var(--muted); font-size: 9.5px; line-height: 1.45; }
.quest-item .q-foot { margin-top: 5px; color: var(--faint); font-size: 8px; display: flex; gap: 10px; flex-wrap: wrap; }
.reward-line { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 5px; }
.reward-line span { border: 1px solid var(--line); border-radius: 5px; padding: 2px 6px; font-size: 8px; color: var(--gold); }

/* ---------- map ---------- */
.map-shell { display: grid; grid-template-columns: minmax(0,1fr) 260px; gap: 16px; }
.map-canvas-wrap { position: relative; border: 1px solid var(--line); border-radius: 14px; overflow: hidden; background: #061018; min-height: 420px; }
#map-canvas { width: 100%; height: 100%; min-height: 420px; }
.map-legend { position: absolute; left: 12px; bottom: 12px; display: flex; gap: 8px; flex-wrap: wrap; }
.map-legend span { font-size: 8px; color: var(--muted); background: rgba(5,16,20,.8); border: 1px solid var(--line); border-radius: 5px; padding: 3px 6px; }
.map-side { display: flex; flex-direction: column; gap: 7px; }
.map-place { display: flex; align-items: center; gap: 9px; padding: 8px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,.02); cursor: pointer; }
.map-place:hover { border-color: var(--line-strong); }
.map-place .icon { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 7px; background: rgba(45,212,191,.1); color: var(--teal); }
.map-place b { display: block; font-size: 10px; }
.map-place small { color: var(--faint); font-size: 8px; }

/* ---------- inventory / shop ---------- */
.item-card { display: flex; gap: 10px; align-items: flex-start; padding: 10px; border: 1px solid var(--line); border-radius: 10px; background: rgba(255,255,255,.02); }
.item-icon { width: 38px; height: 38px; min-width: 38px; display: grid; place-items: center; border-radius: 9px; background: rgba(45,212,191,.1); font-size: 18px; }
.item-card h4 { margin: 0; font-size: 11px; display: flex; gap: 7px; align-items: center; }
.item-card p { margin: 3px 0 0; color: var(--muted); font-size: 9px; line-height: 1.45; }
.item-card .item-foot { margin-top: 5px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.item-card .price { color: var(--gold); font-family: var(--mono); font-size: 10px; }

/* ---------- arena ---------- */
.arena-hero { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.arena-rank { border: 1px solid rgba(255,209,102,.3); border-radius: 13px; padding: 14px; background: radial-gradient(circle at 20% 10%, rgba(255,209,102,.12), rgba(5,16,20,.5)); }
.arena-rank .rank-value { font-family: Georgia, serif; font-size: 38px; color: var(--gold); line-height: 1; }
.arena-rank .rank-name { color: var(--muted); font-size: 10px; text-transform: uppercase; letter-spacing: .12em; }
.arena-stats { display: flex; gap: 14px; margin-top: 12px; }
.arena-stats div b { display: block; font-family: var(--mono); font-size: 16px; }
.arena-stats div span { font-size: 8px; color: var(--faint); text-transform: uppercase; }
.online-pill { display: inline-flex; align-items: center; gap: 6px; color: var(--green); font-size: 9px; }
.online-pill::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: pulse-soft 1.8s infinite; }
@keyframes pulse-soft { 50% { opacity: .45; } }
.invite-box { border: 1px solid var(--line); border-radius: 13px; padding: 14px; background: rgba(5,16,20,.4); }
.invite-box textarea { width: 100%; min-height: 58px; resize: vertical; padding: 9px; border-radius: 8px; border: 1px solid var(--line); background: rgba(2,10,13,.7); color: var(--muted); font-family: var(--mono); font-size: 9px; outline: none; }
.leader-row { display: flex; align-items: center; gap: 9px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.05); font-size: 10px; }
.leader-row .pos { width: 20px; color: var(--faint); font-family: var(--mono); }
.leader-row .name { flex: 1; }
.leader-row .pts { font-family: var(--mono); color: var(--gold); }

/* ---------- dungeon ---------- */
.dungeon-head { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.dungeon-floor { font-family: Georgia, serif; font-size: 30px; color: var(--gold); }
.dungeon-map { display: grid; grid-template-columns: repeat(4, 1fr); gap: 9px; max-width: 480px; margin: 0 auto; }
.dungeon-node {
  aspect-ratio: 1;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(5,16,20,.6);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-size: 8px;
  color: var(--faint);
  cursor: default;
  position: relative;
  transition: .16s;
}
.dungeon-node.revealed { color: var(--muted); border-color: var(--line-strong); background: rgba(19,48,54,.55); }
.dungeon-node.available { border-color: rgba(255,209,102,.7); box-shadow: 0 0 0 1px rgba(255,209,102,.16), inset 0 0 18px rgba(255,209,102,.06); cursor: pointer; animation: node-pulse 1.8s infinite; }
.dungeon-node.available:hover { background: rgba(255,209,102,.13); transform: scale(1.03); }
.dungeon-node.visited { opacity: .6; }
.dungeon-node.current { border-color: var(--teal); box-shadow: 0 0 20px rgba(45,212,191,.22); }
.dungeon-node .node-icon { font-size: 20px; line-height: 1; }
.dungeon-node .node-label { text-transform: uppercase; letter-spacing: .05em; font-size: 7px; }
@keyframes node-pulse { 50% { box-shadow: 0 0 0 1px rgba(255,209,102,.3), inset 0 0 25px rgba(255,209,102,.1); } }
.dungeon-legend { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-top: 14px; }
.dungeon-legend span { font-size: 8px; color: var(--faint); }

/* ---------- battle ---------- */
#battle-root { position: absolute; inset: 0; z-index: 60; overflow: hidden; background: #061014; }
#battle-canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.battle-ui { position: absolute; inset: 0; display: flex; flex-direction: column; pointer-events: none; }
.battle-ui > * { pointer-events: auto; }
