import { chromium } from 'playwright-core'

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium', headless: true,
  args: ['--no-sandbox', '--disable-dev-shm-usage', '--enable-unsafe-swiftshader'],
})
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('console', (m) => { if (m.type() === 'error') errors.push(`CONSOLE: ${m.text()}`) })
page.on('pageerror', (e) => errors.push(`PAGEERROR: ${e.stack || e.message}`))

await page.goto('http://localhost:3002/index.html', { waitUntil: 'networkidle' })
await page.waitForTimeout(900)
await page.click('#btn-new')
await page.waitForTimeout(300)
await page.click('#btn-start-game')
await page.waitForTimeout(900)
await page.click('[data-story-continue]')
await page.waitForTimeout(600)

// Move up with real keyboard input
await page.keyboard.down('KeyW')
await page.waitForTimeout(560)
await page.keyboard.up('KeyW')
await page.waitForTimeout(300)
const pos = await page.evaluate(() => {
  const s = window.__NEXO__.game.state
  return { x: Math.round(s.player.x), y: Math.round(s.player.y), zone: s.world.lastZone, spawns: s.world.spawns.length }
})
console.log('pos after move:', JSON.stringify(pos))
await page.screenshot({ path: '/tmp/opencode/pw/05-world-fixed.png' })

// Interact with Maestra Sol
await page.keyboard.press('KeyE')
await page.waitForTimeout(500)
console.log('npc modal:', await page.isVisible('#modal-root.open'))
await page.screenshot({ path: '/tmp/opencode/pw/06-npc.png' })
await page.click('[data-npc-close]').catch(() => {})
await page.waitForTimeout(400)

// Open each menu
const menus = [
  ['ranch', '07-ranch'], ['codex', '08-codex'], ['journal', '09-journal'],
  ['map', '10-map'], ['inventory', '11-inventory'], ['shop', '12-shop'],
  ['arena', '13-arena'], ['settings', '14-settings'],
]
for (const [menu, shot] of menus) {
  await page.click(`[data-menu="${menu}"]`)
  await page.waitForTimeout(400)
  const open = await page.isVisible('#modal-root.open')
  console.log(`menu ${menu}: ${open}`)
  await page.screenshot({ path: `/tmp/opencode/pw/${shot}.png` })
  const close = await page.$('#modal-root [data-modal-close]')
  if (close) await close.click()
  await page.waitForTimeout(300)
}

// Trigger a wild battle by walking into nearest wild creature
const started = await page.evaluate(() => {
  const g = window.__NEXO__.game
  const s = g.state
  const p = s.player
  let best = null, bestD = Infinity
  for (const w of s.world.spawns) {
    const d = Math.hypot(w.x - p.x, w.y - p.y)
    if (d < bestD) { bestD = d; best = w }
  }
  if (!best) return null
  p.x = best.x; p.y = best.y + 20
  return { species: best.speciesId, level: best.level }
})
console.log('teleport near wild:', JSON.stringify(started))
await page.waitForTimeout(500)
await page.keyboard.press('KeyE')
await page.waitForTimeout(1600)
console.log('battle visible:', await page.isVisible('#battle-root'))
await page.screenshot({ path: '/tmp/opencode/pw/15-battle.png' })

// Click first move
const move = await page.$('#move-grid .move-btn:not([disabled])')
if (move) { await move.click(); await page.waitForTimeout(2500) }
console.log('battle still visible:', await page.isVisible('#battle-root'))
await page.screenshot({ path: '/tmp/opencode/pw/16-battle-turn.png' })

// Try capture subpanel
const capBtn = await page.$('#battle-capture:not([disabled])')
if (capBtn) { await capBtn.click(); await page.waitForTimeout(400); await page.screenshot({ path: '/tmp/opencode/pw/17-capture.png' }) }

console.log('ERRORS:', errors.length ? errors.join('\n') : 'none')
await browser.close()

