}

/* Warmer, cartridge-era logo treatment. */
.title-logo {
  background: linear-gradient(180deg, #fffdf2 0%, #ffe89a 42%, #ffc53d 68%, #e08a12 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 6px 0 rgba(120, 62, 8, 0.55)) drop-shadow(0 18px 34px rgba(255, 197, 61, 0.2));
}
