/* Gold highlight for the active / selected element, echoing the Yellow UI. */
.btn-teal { box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 209, 102, 0.18); }

/* Subtle CRT scanlines over the world, disabled for reduced-motion users. */
#world-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  background: repeating-linear-gradient(180deg, rgba(0, 0, 0, 0.055) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
  opacity: 0.55;
}
@media (prefers-reduced-motion: reduce) {
  #world-shell::after { display: none; }
}
